mapper.select:
SELECT enrollment_status
FROM tb_enrollment
WHERE student_user_no = #{studentUserNo}
  AND course_no = #{courseNo}
LIMIT 1

mapper.update:
UPDATE tb_enrollment
SET enrollment_status = 0
WHERE student_user_no = #{studentUserNo}
  AND course_no = #{courseNo}

mapper.insert:
INSERT INTO tb_enrollment
( student_user_no
, course_no
, enrollment_status
, createdate )
VALUES
( #{studentUserNo}
, #{courseNo}
, #{enrollmentStatus}
, NOW() )

mapper.update:
UPDATE tb_enrollment
SET enrollment_status = 1
WHERE student_user_no = #{studentUserNo}
  AND enrollment_no = #{enrollmentNo}
